            "presentation": {
                "font.size": 14,
                "axes.labelsize": 16,
                "axes.titlesize": 18,  # subplot title
                "figure.titlesize": 22,  # main figure title
                "grid.alpha": 0.5,
                "lines.linewidth": 3,
                "axes.grid": True,
            },
        },
        "plotly": {  # Plotly presets remain for completeness
            "default": {
                "layout": {
                    "xaxis": {"showgrid": False, "showline": True, "gridwidth": 1},
                    "yaxis": {"showgrid": False, "showline": True, "gridwidth": 1},
                    "plot_bgcolor": None,  # Will be set by theme
                    "paper_bgcolor": None,  # Will be set by theme
                }
            },
            "minimal": {
                "layout": {
                    "xaxis": {
                        "showgrid": False,
                        "showline": False,
                        "zeroline": False,
                        "showticklabels": True,
                    },
                    "yaxis": {
                        "showgrid": False,
                        "showline": False,
                        "zeroline": False,
                        "showticklabels": True,
                    },
                }
            },
            "grid": {
                "layout": {
                    "xaxis": {
                        "showgrid": True,
                        "gridwidth": 1,
                        "showline": True,
                        "linewidth": 2,
                    },
                    "yaxis": {
                        "showgrid": True,
                        "gridwidth": 1,
                        "showline": True,
                        "linewidth": 2,
                    },
                }
            },
            "presentation": {
                "layout": {
                    "xaxis": {
                        "showgrid": True,
                        "gridwidth": 1.5,
                        "showline": True,
                        "linewidth": 2,
                        "tickfont": {"size": 14},
                        "title": {"font": {"size": 16}},
                    },
                    "yaxis": {
                        "showgrid": True,
