                if (
                    "cumulative_variance" in current_criteria
                    or "all" in current_criteria
                ):
                    target_ax_for_cum_var = ax2 if ax2_used else ax.twinx()
                    if not ax2_used:
                        target_ax_for_cum_var.set_ylabel(
                            "Cumulative Variance (%)", color=self.colors["accent_color"]
                        )
